scripts.script:
local Rayfield = loadstring(game:HttpGet("https://sirius.menu/gen2"))()

local window = Rayfield:CreateWindow({
    name = "PyteHUB | Dog Pound",
    subtitle = "developed by JCDEV | ALPHA 1 | Rayfield lib Gen2",
    sidebarLayout = true,
    theme = "Rose"
})

local mtab = window:CreateTab({ name = "Main", icon = nil })
local ttab = window:CreateTab({ name = "Teleports", icon = nil })
local etab = window:CreateTab({ name = "Exploits", icon = nil })

mtab:CreateSlider({
    name = "Field of view",
    range = { 70, 120 },
    increment = 1,
    value = 90,
    suffix = "°",
    callback = function(value)
        workspace.CurrentCamera.FieldOfView = value
    end,
})

mtab:CreateDivider()

mtab:CreateSlider({
    name = "Walkspeed",
    range = { 1, 300 },
    increment = 1,
    value = 16,
    suffix = "",
    callback = function(value)
        game.Players.LocalPlayer.Character.Humanoid.WalkSpeed = value
    end,
})

ttab:CreateButton({
    name = "Guard spawn",
    callback = function()
        game.Players.LocalPlayer.Character.HumanoidRootPart.CFrame = game.workspace.Map.GuardsRoom:GetChildren()[33].CFrame
    end,
})

ttab:CreateDivider()

ttab:CreateButton({
    name = "Dog spawn",
    callback = function()
        game.Players.LocalPlayer.Character.HumanoidRootPart.CFrame = game.workspace.Map.Floor:GetChildren()[21].CFrame
    end,
})
